#include "../mage_prefill_m89d_t32_microtile/mage_prefill_m89d_t32_microtile.hpp"
#include <iostream>
#include <random>
void m89p_fourshard(hls::stream<m89_axis128_t>&,const ap_uint<128>*,const ap_uint<128>*,const ap_uint<128>*,const ap_uint<128>*,hls::stream<m89_axis64_t>&,unsigned,unsigned,unsigned,ap_uint<32>&,ap_uint<32>&,ap_uint<32>&,ap_uint<32>&);
static void put(ap_uint<128>&lo,ap_uint<128>&hi,unsigned l,unsigned b,unsigned v){if(b==2)lo.range(2*l+1,2*l)=v;else if(l<32)lo.range(4*l+3,4*l)=v;else hi.range(4*(l-32)+3,4*(l-32))=v;}
static int qmin(unsigned b,bool o){int h=1<<(b-1);return o?-h+1:-h;}
static int run(unsigned bits){const unsigned G=3,R=16,B=2,S=4,W=1+4*bits;static ap_uint<128>m[S][M89_MAX_GROUPS*(M89_MAX_ROWS_PER_SHARD/8)*17];static ap_int<8>a[G][M89_TOKEN_LANES][64];static int e[M89_TOKEN_LANES][S][R];hls::stream<m89_axis128_t>tx;hls::stream<m89_axis64_t>rx;std::mt19937 gen(0x4d383950+bits);std::uniform_int_distribution<int>ad(-31,31),cd(0,(1<<bits)-1),bd(0,1);for(unsigned g=0;g<G;++g)for(unsigned t=0;t<32;++t){for(unsigned l=0;l<64;++l)a[g][t][l]=ad(gen);for(unsigned w=0;w<4;++w){m89_axis128_t i;i.data=0;for(unsigned x=0;x<16;++x)i.data.range(8*x+7,8*x)=(ap_uint<8>)a[g][t][16*w+x];i.keep=-1;i.strb=-1;i.last=g+1==G&&t==31&&w==3;tx.write(i);}}for(unsigned t=0;t<32;++t)for(unsigned s=0;s<S;++s)for(unsigned r=0;r<R;++r)e[t][s][r]=0;for(unsigned s=0;s<S;++s)for(unsigned g=0;g<G;++g)for(unsigned bl=0;bl<B;++bl){unsigned base=g*B*W+bl*W;ap_uint<128>sc=0;bool o[8];for(unsigned r=0;r<8;++r){o[r]=bd(gen);sc.range(16*r+15,16*r)=(ap_uint<16>)o[r]<<15;}m[s][base]=sc;for(unsigned p=0;p<4;++p){ap_uint<128>l0=0,h0=0,l1=0,h1=0;for(unsigned l=0;l<64;++l){int c0=cd(gen),c1=cd(gen);put(l0,h0,l,bits,c0);put(l1,h1,l,bits,c1);for(unsigned t=0;t<32;++t){e[t][s][8*bl+2*p]+=a[g][t][l]*(qmin(bits,o[2*p])+c0);e[t][s][8*bl+2*p+1]+=a[g][t][l]*(qmin(bits,o[2*p+1])+c1);}}unsigned at=base+1+p*bits;m[s][at]=l0;if(bits==4)m[s][at+1]=h0;m[s][at+bits/2]=l1;if(bits==4)m[s][at+bits/2+1]=h1;}}ap_uint<32>st,bu,ca,ma;m89p_fourshard(tx,m[0],m[1],m[2],m[3],rx,G,R,bits,st,bu,ca,ma);if(st||bu!=0x4D383950U||ca!=1||ma!=G*R*S*32)return 1;for(unsigned bl=0;bl<B;++bl)for(unsigned t=0;t<32;++t)for(unsigned s=0;s<S;++s)for(unsigned p=0;p<4;++p){m89_axis64_t i=rx.read();unsigned r=8*bl+2*p;if((int)(ap_int<32>)i.data.range(31,0)!=e[t][s][r]||(int)(ap_int<32>)i.data.range(63,32)!=e[t][s][r+1])return 1;}return rx.empty()?0:1;}
int main(){if(run(2)||run(4))return 1;std::cout<<"M89P_FOURSHARD_T32_W2W4_CSIM_PASS"<<std::endl;return 0;}
